<?php
require __DIR__.'/bootstrap.php';require_once __DIR__.'/lib/FinanceOperations.php';
$auth->requireAbility('finance');$church=$auth->currentChurch();if(!$church)redirect('/dashboard.php');
$cid=(string)$church['id'];$ops=new FinanceOperations($pdo,$auth,$cid);$registry=new RegistryService($pdo,$auth,$cid);
$view=(string)($_GET['view']??'overview');if(!in_array($view,['overview','receivables','report','history','periods'],true))$view='overview';
$error=null;
if($_SERVER['REQUEST_METHOD']==='POST')try{
    verify_csrf();$action=(string)($_POST['action']??'');
    if($action==='receivable')$ops->createReceivables($_POST);
    elseif($action==='receive')$ops->receive((string)($_POST['id']??''),$_POST);
    elseif($action==='lock_period')FinancePeriodGuard::close($pdo,$auth,$cid,(string)($_POST['from']??''),(string)($_POST['to']??''),(string)($_POST['reason']??''));
    elseif($action==='reopen_period')FinancePeriodGuard::reopen($pdo,$auth,$cid,(string)($_POST['id']??''));
    elseif($action==='cancel')$ops->cancel((string)($_POST['id']??''));
    else throw new InvalidArgumentException('Ação inválida.');
    flash('success','Operação registrada.');redirect('/finance-control.php?view='.(in_array($action,['lock_period','reopen_period'],true)?'periods':'receivables'));
}catch(Throwable $e){$error=$e instanceof PDOException?'Não foi possível registrar a operação. Revise os campos e tente novamente.':$e->getMessage();}
$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-t'));$center=trim((string)($_GET['center']??''))?:null;
$entries=[];try{$entries=$ops->entries($from,$to,$center);}catch(Throwable $e){$error=$e->getMessage();}
$receivables=$ops->receivables();$centers=$registry->all('cost_center',true);$contacts=$registry->all('contact');$categories=$registry->all('finance_category');
$q=$pdo->prepare('SELECT id,name FROM finance_accounts WHERE church_id=? AND active=1 ORDER BY name');$q->execute([$cid]);$accounts=$q->fetchAll();
$q=$pdo->prepare('SELECT id,name FROM members WHERE church_id=? AND active=1 ORDER BY name');$q->execute([$cid]);$people=$q->fetchAll();
$receivableTotal=0;$receivableLate=0;$income=0;$expense=0;$todayIncome=0;$todayExpense=0;
foreach($receivables as $r)if($r['status']==='active'){$receivableTotal+=FinanceOperations::cents($r['outstanding']);if($r['due_date']<date('Y-m-d'))$receivableLate+=FinanceOperations::cents($r['outstanding']);}
foreach($entries as $entry)if($entry['status']==='posted'){if($entry['direction']==='income')$income+=FinanceOperations::cents($entry['amount']);else $expense+=FinanceOperations::cents($entry['amount']);}
$q=$pdo->prepare("SELECT direction,COALESCE(SUM(amount),0) amount FROM finance_entries WHERE church_id=? AND status='posted' AND transaction_date=CURDATE() GROUP BY direction");$q->execute([$cid]);foreach($q->fetchAll() as $row)if($row['direction']==='income')$todayIncome=FinanceOperations::cents($row['amount']);else $todayExpense=FinanceOperations::cents($row['amount']);
$q=$pdo->prepare("SELECT COALESCE(SUM(amount),0) total,COALESCE(SUM(CASE WHEN due_date<CURDATE() THEN amount ELSE 0 END),0) late FROM finance_payables WHERE church_id=? AND status='open'");$q->execute([$cid]);$payables=$q->fetch();
function control_money(int $cents): string{return 'R$ '.number_format($cents/100,2,',','.');}
if(($_GET['export']??'')==='csv'&&!$error){
    header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="movimentacoes.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");
    fputcsv($out,['Data','Tipo','Categoria','Descrição','Membro','Conta','Centro de custos','Valor','Situação'],';','"','');
    foreach($entries as $r){$values=[$r['transaction_date'],$r['direction']==='income'?'Entrada':'Saída',$r['category'],$r['description'],$r['member_name']??'',$r['account_name']??'',$r['cost_center_name']??'',$r['amount'],$r['status']];foreach($values as $i=>$v)if($i!==7&&preg_match('/^[\s]*[=+@-]/u',(string)$v))$values[$i]="'".$v;fputcsv($out,$values,';','"','');}fclose($out);exit;
}
$labels=['overview'=>'Resumo financeiro','receivables'=>'Valores a receber','report'=>'Relatório e exportação','history'=>'Histórico financeiro','periods'=>'Bloqueio de períodos'];
View::header($labels[$view],$auth,'finance-control.php');View::flash();
?>
<section class="module-toolbar"><div class="module-title"><h1><?=e($labels[$view])?></h1><p>Entradas, compromissos e organização da tesouraria.</p></div><div class="actions"><a class="btn btn-light" href="/finance.php">Abrir livro caixa</a><a class="btn btn-light" href="/finance-import.php">Importar CSV</a><?php if($view==='receivables'):?><button class="btn btn-primary" type="button" data-open-dialog="receivable-editor">＋ Novo valor a receber</button><?php endif?></div></section>
<nav class="portal-tabs" aria-label="Financeiro"><?php foreach($labels as $key=>$label):?><a href="?view=<?=e($key)?>" <?=$view===$key?'aria-current="page"':''?>><?=e($label)?></a><?php endforeach?><a href="/registers.php?kind=finance_category">Cadastros financeiros</a></nav>
<?php if($error):?><div class="alert alert-error" role="alert"><?=e($error)?></div><?php endif?>
<?php if($view==='overview'):?>
<div class="grid stats portal-stats"><?php foreach(['Recebido hoje'=>$todayIncome,'Pago hoje'=>$todayExpense,'Total a receber'=>$receivableTotal,'Recebimentos em atraso'=>$receivableLate,'Total a pagar'=>FinanceOperations::cents($payables['total']),'Pagamentos em atraso'=>FinanceOperations::cents($payables['late'])] as $label=>$value):?><div class="card stat"><div class="stat-label"><?=e($label)?></div><div class="stat-value"><?=control_money($value)?></div></div><?php endforeach?></div>
<div class="dashboard-actions"><a class="dashboard-action" href="?view=receivables"><span><strong>Controlar recebimentos</strong><small>Previsões, parcelas e baixas parciais</small></span></a><a class="dashboard-action" href="/finance.php#payables"><span><strong>Contas a pagar</strong><small>Vencimentos e pagamentos</small></span></a><a class="dashboard-action" href="?view=report"><span><strong>Prestação de contas</strong><small>Filtro por centro de custos e exportação</small></span></a></div>
<section class="card card-pad"><h2>Cadastros da tesouraria</h2><div class="actions"><?php foreach(['finance_category'=>'Categorias','contact'=>'Contatos e fornecedores','cost_center'=>'Centros de custos'] as $key=>$label):?><a class="btn btn-light" href="/registers.php?kind=<?=e($key)?>"><?=e($label)?></a><?php endforeach?></div><p class="muted">Valores a receber são compromissos ou previsões cadastrados pela tesouraria. Não são cobranças automáticas de dízimos dos membros.</p></section>
<?php elseif($view==='receivables'):
$status=(string)($_GET['status']??'open');
$filtered=array_values(array_filter($receivables,static function(array $r)use($status): bool {
    if($status==='all')return true;
    if($status==='cancelled')return $r['status']==='cancelled';
    if($r['status']!=='active')return false;
    $outstanding=FinanceOperations::cents($r['outstanding']);
    if($status==='received')return $outstanding===0;
    if($status==='late')return $outstanding>0&&$r['due_date']<date('Y-m-d');
    return $outstanding>0;
}));
$page=max(1,(int)($_GET['page']??1));$pages=max(1,(int)ceil(count($filtered)/50));$page=min($page,$pages);$shown=array_slice($filtered,($page-1)*50,50);
?>
<section class="card card-pad"><form method="get" class="portal-filter"><input type="hidden" name="view" value="receivables"><label>Situação<select class="select" name="status"><?php foreach(['open'=>'Em aberto','late'=>'Em atraso','received'=>'Recebidos','cancelled'=>'Cancelados','all'=>'Todos'] as $key=>$label):?><option value="<?=e($key)?>" <?=$status===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><button class="btn btn-light">Filtrar</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Vencimento</th><th>Pagador / descrição</th><th>Parcela</th><th>Previsto</th><th>Recebido</th><th>Em aberto</th><th>Ações</th></tr></thead><tbody>
<?php foreach($shown as $r):?><tr><td><?=date('d/m/Y',strtotime($r['due_date']))?></td><td><strong><?=e($r['payer_name'])?></strong><div><?=e($r['description'])?></div><small><?=e($r['category'])?></small></td><td><?=(int)$r['installment_number']?>/<?=(int)$r['installment_count']?></td><td><?=control_money(FinanceOperations::cents($r['amount']))?></td><td><?=control_money(FinanceOperations::cents($r['received']))?></td><td><?=control_money(FinanceOperations::cents($r['outstanding']))?></td><td><?php if($r['status']==='cancelled'):?>Cancelado<?php elseif(FinanceOperations::cents($r['outstanding'])===0):?><span class="badge ok">Recebido</span><?php else:?><details><summary class="btn btn-light">Registrar recebimento</summary><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="receive"><input type="hidden" name="id" value="<?=e($r['id'])?>"><input type="hidden" name="request_key" value="<?=bin2hex(random_bytes(32))?>"><label>Valor recebido<input class="input" name="amount" value="<?=e(str_replace('.',',',$r['outstanding']))?>" inputmode="decimal" required></label><label>Data<input class="input" name="received_at" type="date" value="<?=date('Y-m-d')?>" required></label><label>Conta<select class="select" name="account_id"><option value="">Conta prevista / sem conta</option><?php foreach($accounts as $a):?><option value="<?=e($a['id'])?>"><?=e($a['name'])?></option><?php endforeach?></select></label><button class="btn btn-primary">Confirmar recebimento</button></form></details><?php if(FinanceOperations::cents($r['received'])===0):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="btn btn-light">Cancelar previsão</button></form><?php endif;endif?></td></tr><?php endforeach?><?php if(!$shown):?><tr><td colspan="7"><div class="empty">Nenhum registro nesta situação.</div></td></tr><?php endif?></tbody></table></div><p>Página <?=$page?> de <?=$pages?> · <?=count($filtered)?> registros</p><div class="actions"><?php if($page>1):?><a class="btn btn-light" href="?view=receivables&status=<?=e($status)?>&page=<?=$page-1?>">Anterior</a><?php endif?><?php if($page<$pages):?><a class="btn btn-light" href="?view=receivables&status=<?=e($status)?>&page=<?=$page+1?>">Próxima</a><?php endif?></div></section>
<?php elseif($view==='report'):?>
<section class="card card-pad"><form class="portal-filter" method="get"><input type="hidden" name="view" value="report"><label>De<input class="input" type="date" name="from" value="<?=e($from)?>" required></label><label>Até<input class="input" type="date" name="to" value="<?=e($to)?>" required></label><label>Centro de custos<select class="select" name="center"><option value="">Todos</option><?php foreach($centers as $c):?><option value="<?=e($c['id'])?>" <?=$center===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></label><button class="btn btn-primary">Consultar</button><button class="btn btn-light" name="export" value="csv">Exportar CSV</button><button class="btn btn-light no-print" type="button" onclick="window.print()">Imprimir / PDF</button></form></section>
<div class="grid stats portal-stats"><?php foreach(['Entradas'=>$income,'Saídas'=>$expense,'Resultado'=>$income-$expense] as $label=>$value):?><div class="card stat"><div class="stat-label"><?=e($label)?></div><div class="stat-value"><?=control_money($value)?></div></div><?php endforeach?></div>
<section class="card card-pad"><h2><?=e($church['name'])?> · Movimentações do período</h2><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Conta</th><th>Centro de custos</th><th>Valor</th><th>Situação</th></tr></thead><tbody><?php foreach($entries as $r):?><tr><td><?=e($r['transaction_date'])?></td><td><?=e($r['description'])?></td><td><?=e($r['category'])?></td><td><?=e($r['account_name'])?></td><td><?=e($r['cost_center_name'])?></td><td><?=$r['direction']==='income'?'+':'−'?> <?=control_money(FinanceOperations::cents($r['amount']))?></td><td><?=$r['status']==='posted'?'Registrado':'Estornado'?></td></tr><?php endforeach?></tbody></table></div><p class="muted">Os totais consideram apenas lançamentos ativos. Estornos permanecem no histórico.</p></section>
<?php elseif($view==='periods'):
$q=$pdo->prepare('SELECT * FROM finance_period_locks WHERE church_id=? ORDER BY active DESC,period_end DESC');$q->execute([$cid]);$locks=$q->fetchAll();
?>
<section class="card card-pad"><h2>Proteger um período conferido</h2><p>Impede novos lançamentos, recebimentos e estornos nas datas bloqueadas, inclusive nos caixas dos departamentos. A administração pode reabrir o período; o histórico é preservado.</p><form method="post" class="portal-filter"><?=csrf_field()?><input type="hidden" name="action" value="lock_period"><label>Início<input type="date" class="input" name="from" required></label><label>Fim<input type="date" class="input" name="to" required></label><label>Justificativa<input class="input" name="reason" required maxlength="1000"></label><button class="btn btn-primary">Bloquear período</button></form></section>
<section class="card card-pad"><div class="table-wrap"><table class="table"><thead><tr><th>Período</th><th>Justificativa</th><th>Situação</th><th>Ações</th></tr></thead><tbody><?php foreach($locks as $lock):?><tr><td><?=e($lock['period_start'])?> a <?=e($lock['period_end'])?></td><td><?=e($lock['reason'])?></td><td><?=$lock['active']?'Bloqueado':'Reaberto'?></td><td><?php if($lock['active']&&$auth->can('settings')):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="reopen_period"><input type="hidden" name="id" value="<?=e($lock['id'])?>"><button class="btn btn-light">Reabrir período</button></form><?php endif?></td></tr><?php endforeach?><?php if(!$locks):?><tr><td colspan="4">Nenhum período bloqueado.</td></tr><?php endif?></tbody></table></div></section>
<?php else:?>
<section class="card card-pad"><h2>Últimas 200 ações</h2><p class="muted">Recebimentos, caixas de departamentos e cadastros financeiros. Os estornos e seus motivos também permanecem no livro caixa.</p><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Ação</th></tr></thead><tbody><?php foreach($ops->auditRows() as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e(['receivable_created'=>'Previsão de recebimento criada','receivable_received'=>'Recebimento registrado','receivable_cancelled'=>'Previsão cancelada','department_cash_enabled'=>'Caixa de departamento ativado','department_entry_created'=>'Lançamento de departamento','department_entry_reversed'=>'Estorno de departamento','registry_saved'=>'Cadastro atualizado','registry_archived'=>'Cadastro arquivado','registry_restored'=>'Cadastro restaurado','finance_period_locked'=>'Período bloqueado','finance_period_reopened'=>'Período reaberto','finance_csv_imported'=>'Arquivo CSV importado','finance_entry_created'=>'Lançamento financeiro registrado','finance_entry_reversed'=>'Lançamento financeiro estornado'][$r['action']]??$r['action'])?></td></tr><?php endforeach?></tbody></table></div></section>
<?php endif?>
<dialog class="app-dialog" id="receivable-editor" aria-labelledby="receivable-title" <?=($error&&($_POST['action']??'')==='receivable')?'data-auto-open':''?>><div class="dialog-shell"><header class="dialog-heading"><div><h2 id="receivable-title">Novo valor a receber</h2><p>Compromisso ou previsão da tesouraria.</p></div><button class="icon-button" type="button" data-close-dialog aria-label="Fechar">×</button></header><div class="dialog-body"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="receivable"><div class="form-grid"><label class="full">Pagador *<input class="input" name="payer_name" required maxlength="190"></label><label class="full">Descrição *<input class="input" name="description" required maxlength="255"></label><label>Categoria *<input class="input" name="category" list="operation-categories" required maxlength="160"></label><label>Valor por parcela *<input class="input" name="amount" inputmode="decimal" placeholder="0,00" required></label><label>Primeiro vencimento *<input class="input" type="date" name="due_date" value="<?=date('Y-m-d')?>" required></label><label>Número de parcelas mensais<input class="input" type="number" name="installments" value="1" min="1" max="36"></label><label>Membro vinculado<select class="select" name="member_id"><option value="">Não vincular</option><?php foreach($people as $p):?><option value="<?=e($p['id'])?>"><?=e($p['name'])?></option><?php endforeach?></select></label><label>Conta prevista<select class="select" name="account_id"><option value="">Não informar</option><?php foreach($accounts as $a):?><option value="<?=e($a['id'])?>"><?=e($a['name'])?></option><?php endforeach?></select></label><label>Centro de custos<select class="select" name="cost_center_id"><option value="">Não informar</option><?php foreach($centers as $c):if(!$c['active'])continue;?><option value="<?=e($c['id'])?>"><?=e($c['name'])?></option><?php endforeach?></select></label><label>Contato cadastrado<select class="select" name="contact_id"><option value="">Não vincular</option><?php foreach($contacts as $c):?><option value="<?=e($c['id'])?>"><?=e($c['name'])?></option><?php endforeach?></select></label></div><p class="muted">Uma previsão não entra no saldo. O caixa recebe o valor somente quando você registra o recebimento.</p><button class="btn btn-primary">Salvar previsão</button></form></div></div></dialog>
<datalist id="operation-categories"><?php foreach($categories as $c):if(($c['data']['direction']??'both')==='expense')continue;?><option value="<?=e($c['name'])?>"><?php endforeach?></datalist>
<?php View::footer();
